// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RobotSessionTurn) predicate.RobotSessionTurn {
	return predicate.RobotSessionTurn(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RobotSessionTurn) predicate.RobotSessionTurn {
	return predicate.RobotSessionTurn(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RobotSessionTurn) predicate.RobotSessionTurn {
	return predicate.RobotSessionTurn(sql.NotPredicates(p))
}
